INSERT OR REPLACE INTO p_studio_batch (id, act_id, num, br_batch_id, name, brief_json, setup_json, plan_json, status) VALUES ('955e149acf3af48d87fdaf4a', 'brand_bonk_golf', NULL, NULL, 'Black Friday: bundle + B2G1 hats (real photos only)', '{"angle": "Black Friday Nov 27 to 30: the five-piece set (hat, marker, divot tool, towel, tees) $125.75 of gear for $92.95, and Buy 2 Get 1 Free on hats only.", "why": "In BFCM 2025 the evergreen heroes beat the offer ads, so the gift and hero lines carry the offer; 325-2 (one price) and 235 B (gift line) are the strongest signals.", "concept": "Real bonkgolf.com photos only (Floyd: no AI imagery). Every line already has its finished image. Line 25 (unbox video) is not here: needs footage.", "post_copy": "Black Friday at BONK. The whole setup, hat, ball marker, divot tool, towel and tees, for $92.95. Or buy 2 hats and get 1 free. Nov 27 to 30.", "testing": "concepts", "lines": [{"text": "bf-01: Everything a golfer needs. Gift set photo, price.", "inspo": [], "photo": "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/8a94f16ec2348786e957091e.png"}, {"text": "bf-02: Receipt: five pieces itemized, total struck, you pay.", "inspo": [], "photo": "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/e4ad91185ec653ddf554a22e.png"}, {"text": "bf-03: 5 pieces. 1 price. (325-2 rebuilt, dark).", "inspo": [], "photo": "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/9e0256e885fe82513d0979a6.png"}, {"text": "bf-04: Retire his old cap + the rest of the setup (235 B line).", "inspo": [], "photo": "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/0367c8fbd88eeea42b1443ca.png"}, {"text": "bf-05: Skip the gift card (298-4 line).", "inspo": [], "photo": "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/c59b97a63ecad4653cccc6fa.png"}, {"text": "bf-06: Review: used every piece.", "inspo": [], "photo": "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/c373354206d26790dfa2c452.png"}, {"text": "bf-07: One at a time vs the box.", "inspo": [], "photo": "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/7626c8674c3239da327f3223.png"}, {"text": "bf-08: Black Friday, type-led, dark.", "inspo": [], "photo": "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/034a14f2fdf3a8d3b0539d21.png"}, {"text": "bf-09: Every piece fits the hat (callouts).", "inspo": [], "photo": "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/d6f54e509f545bbbc3d493ab.png"}, {"text": "bf-10: You don''t need to know golf (to the gifter).", "inspo": [], "photo": "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/b550e2043c9aaf7e7e232282.png"}, {"text": "bf-11: Buy 2 hats, get 1 free. Three hats.", "inspo": [], "photo": "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/6cbdcb799c5ae5af579ca3a3.png"}, {"text": "bf-12: One for you, two for the group.", "inspo": [], "photo": "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/1ef240ff5f7919c3a07c53f6.png"}, {"text": "bf-13: Three gifts, pay for two.", "inspo": [], "photo": "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/44f6c7772478d040943211dc.png"}, {"text": "bf-14: Dad. Son. You. Youth hats count.", "inspo": [], "photo": "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/04ec0a11d59f8dd0c40bfa72.png"}, {"text": "bf-15: All three black ones.", "inspo": [], "photo": "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/f132f08c00152fd489b4d737.png"}, {"text": "bf-16: Review: his and hers.", "inspo": [], "photo": "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/8a2976e156b6bbfc0ef70743.png"}, {"text": "bf-17: Lefties count too (Southpaw).", "inspo": [], "photo": "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/2c7cbde90cd3805428a0429b.png"}, {"text": "bf-18: Fitted counts too (PF 2.0, no sweat-stain claim).", "inspo": [], "photo": "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/e5b21f172b1bc5d86eb4ccbe.png"}, {"text": "bf-19: B2G1 type-led, dark.", "inspo": [], "photo": "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/42a4f869b7ca616b4b0a485d.png"}, {"text": "bf-20: Two deals, one card.", "inspo": [], "photo": "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/cd683e1d993d2ea1f77959c9.png"}, {"text": "bf-21: Ends Monday (run Nov 29 to 30).", "inspo": [], "photo": "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/6bdcf773d8ce0333c173303e.png"}, {"text": "bf-22: Cyber Monday last day (run Nov 30 only).", "inspo": [], "photo": "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/103a0843cd402ae8691b93f1.png"}, {"text": "bf-23: Sticker on ebf-01 (the anchor).", "inspo": [], "photo": "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/4f4c37de686d79edd13bc6f4.png"}, {"text": "bf-24: Sticker on ebf-06.", "inspo": [], "photo": "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/2f3de435ea8bea0900ffbda6.png"}], "source": "Bonk BFCM ads chat, 2026-10-14 (docs/bfcm-bonk-concepts.md, Batch 2)", "reference": "docs/bfcm-bonk-concepts.md"}', '{"products": [], "images": ["https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/8a94f16ec2348786e957091e.png", "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/e4ad91185ec653ddf554a22e.png", "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/9e0256e885fe82513d0979a6.png", "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/0367c8fbd88eeea42b1443ca.png", "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/c59b97a63ecad4653cccc6fa.png", "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/c373354206d26790dfa2c452.png", "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/7626c8674c3239da327f3223.png", "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/034a14f2fdf3a8d3b0539d21.png", "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/d6f54e509f545bbbc3d493ab.png", "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/b550e2043c9aaf7e7e232282.png", "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/6cbdcb799c5ae5af579ca3a3.png", "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/1ef240ff5f7919c3a07c53f6.png"], "swipe": []}', NULL, 'draft');
